{
  "implementation": "def solve(case):
    nodes = case['nodes']
    node_map = {n['id']: n for n in nodes}
    # validate root
    root = None
    for n in nodes:
        if n['parent'] is None:
            if root is not None:
                raise ValueError('Multiple roots')
            root = n['id']
    if root is None:
        raise ValueError('No root')
    required_symbols = set(case['required_symbols'])
    all_symbols = set(n['symbol'] for n in nodes)
    if not required_symbols.issubset(all_symbols):
        raise ValueError('Required symbols missing from tree')
    retained = set(n['id'] for n in nodes)
    symbol_counts = {}
    for n in nodes:
        sym = n['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if nid == root:
            continue
        if not n['removable']:
            continue
        # check retained children
        has_retained_child = any(
            other['parent'] == nid for other in nodes if other['id'] in retained
        )
        if has_retained_child:
            continue
        # check required symbols after removal
        ok = True
        for sym in required_symbols:
            cnt = symbol_counts[sym] - (1 if n['symbol'] == sym else 0)
            if cnt < 1:
                ok = False
                break
        if not ok:
            continue
        retained.discard(nid)
        symbol_counts[n['symbol']] -= 1
        removed.append(nid)
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"
}
